$ErrorActionPreference='Stop'
$repo=(Get-Location).Path
$inventory=Get-Content docs/ai/wiki-tools-audit-20261024.inventory.json -Raw|ConvertFrom-Json
$edges=[Collections.Generic.List[object]]::new()
foreach($file in @($inventory.files|Where-Object path -like '*.ps1')) {
  $tokens=$null;$errors=$null
  $ast=[Management.Automation.Language.Parser]::ParseFile((Join-Path $repo $file.path),[ref]$tokens,[ref]$errors)
  if($errors.Count) { throw "Parse failure: $($file.path)" }
  $bindings=@{}
  foreach($assignment in $ast.FindAll({param($n) $n -is [Management.Automation.Language.AssignmentStatementAst]},$true)) {
    $key=$assignment.Left.Extent.Text
    $targets=@([regex]::Matches($assignment.Right.Extent.Text,"['`"]([^'`"/\\]+\.(?:ps1|mjs))['`"]")|ForEach-Object {$_.Groups[1].Value})
    if($targets.Count -gt 0) {$bindings[$key]=$targets}
  }
  foreach($command in $ast.FindAll({param($n) $n -is [Management.Automation.Language.CommandAst]},$true)) {
    $name=$command.GetCommandName();$text=$command.Extent.Text
    $targets=@()
    $kind=''
    if($command.InvocationOperator -in @([Management.Automation.Language.TokenKind]::Ampersand,[Management.Automation.Language.TokenKind]::Dot)) {
      $targetText=$command.CommandElements[0].Extent.Text
      $targets=@([regex]::Matches($targetText,"['`"]([^'`"/\\]+\.(?:ps1|mjs))['`"]")|ForEach-Object {$_.Groups[1].Value})
      $kind='syntactic call/import'
      if(-not $targets.Count -and $bindings.ContainsKey($targetText)) {$targets=$bindings[$targetText];$kind='call through statically bound variable (flow-insensitive)'}
    } elseif($name -in @('Invoke-WikiTool','Invoke-JsonTool','Invoke-LlmWikiAssessment','Invoke-LlmWikiReadOnlyTool','Invoke-ObservedWikiStage')) {
      $targets=@([regex]::Matches($text,"['`"]([^'`"/\\]+\.(?:ps1|mjs))['`"]")|ForEach-Object {$_.Groups[1].Value})
      $kind='explicit filename passed to existing tool dispatcher'
    }
    foreach($target in $targets) {$edges.Add([ordered]@{source=$file.path;line=$command.Extent.StartLineNumber;targetLeaf=$target;kind=$kind;witness=($text -split "`r?`n")[0]})}
  }
}
$edges|ConvertTo-Json -Depth 8|Set-Content .artifacts/wiki-tools-audit-20261024/static-calls.json -Encoding utf8
Write-Output "static PowerShell call/import edges=$($edges.Count)"

