    # Generated and historical reports are navigation, never current callers.
    # Excluding census JSON also prevents self-reference graph inflation.
    if f.startswith(('.llm-wiki/generated/', 'docs/reports/')) or 'wiki-tools-audit-20261024' in f:
        continue
    if pathlib.Path(f).suffix.lower() not in {'.ps1','.psd1','.mjs','.cjs','.js','.ts','.cs','.csproj','.props','.targets','.json','.md','.yml','.yaml','.toml','.sh','.cmd'} and '/.husky/' not in f:
